import{_ as i,W as e,s as l,u as r,ah as o,I as u,w as n,Z as a,A as p}from"./chunks/framework.DPWZnL3N.js";import"./chunks/theme.DZmP8ALZ.js";const h=JSON.parse('{"title":"如何不重装修复损坏的 Ubuntu 系统 | LCTT x X-CMD","titleTemplate":false,"description":"如何不重装修复损坏的 Ubuntu 系统 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何不重装修复损坏的 Ubuntu 系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何不重装修复损坏的 Ubuntu 系统 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181205 How To Fix Broken Ubuntu OS Without Reinstalling It","title":"如何不重装修复损坏的 Ubuntu 系统","tag":"201812"},"relativePath":"201812/20181205 How To Fix Broken Ubuntu OS Without Reinstalling It.md","filePath":"[post].md"}'),d={name:"201812/20181205 How To Fix Broken Ubuntu OS Without Reinstalling It.md"};function b(g,t,m,T,f,w){const s=e("Link");return r(),l("div",null,[t[20]||(t[20]=o('<h1 id="如何不重装修复损坏的-ubuntu-系统" tabindex="-1">如何不重装修复损坏的 Ubuntu 系统 <a class="header-anchor" href="#如何不重装修复损坏的-ubuntu-系统" aria-label="Permalink to 如何不重装修复损坏的 Ubuntu 系统">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/12/Fix-Broken-Ubuntu-OS-720x340.jpg" alt=""></p><p>今天，我在升级我的 Ubuntu 18.04 LTS 系统。不幸的是，在更新 Ubuntu 时中途断电，系统关机。电源恢复后，我再次启动系统。在登录页面输入密码后，它变成空白并且没有响应。键盘和鼠标也没有作用。我只看到一个空白的屏幕！值得庆幸的是，它只是一台测试机，并且没有重要的数据。我可以直接擦除整个系统然后重新安装。但是，我不想这样做。由于我没有什么可失去的，我只是想不重装修复我损坏的 Ubuntu 系统，并且我成功了！如果你发现自己处于像我这样的境地，不要惊慌。这个简短的教程描述了如何在不丢失数据的情况下轻松修复损坏的 Ubuntu 系统，而无需重新安装。</p><h3 id="修复损坏的-ubuntu-系统" tabindex="-1">修复损坏的 Ubuntu 系统 <a class="header-anchor" href="#修复损坏的-ubuntu-系统" aria-label="Permalink to 修复损坏的 Ubuntu 系统">​</a></h3><p>首先，尝试使用 live cd 登录并<strong>在外部驱动器中备份数据</strong>。以防这个方法没用，你仍然可以获取数据并重新安装系统！</p>',5)),u("p",null,[t[1]||(t[1]=n("在登录页上，按下 ")),t[2]||(t[2]=u("code",null,"CTRL+ALT+F1",-1)),t[3]||(t[3]=n(" 切换到 tty1。你可以在")),a(s,{href:"https://www.ostechnix.com/how-to-switch-between-ttys-without-using-function-keys-in-linux/"},{default:p(()=>t[0]||(t[0]=[n("此处")])),_:1}),t[4]||(t[4]=n("了解有关在 TTY 之间切换的更多信息。"))]),t[21]||(t[21]=o(`<p>现在，逐个输入以下命令来修复损坏的 Ubuntu Linux。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo rm /var/lib/apt/lists/lock</span></span>
<span class="line"><span>$ sudo rm /var/lib/dpkg/lock</span></span>
<span class="line"><span>$ sudo rm /var/lib/dpkg/lock-frontend</span></span>
<span class="line"><span>$ sudo dpkg --configure -a</span></span>
<span class="line"><span>$ sudo apt clean</span></span>
<span class="line"><span>$ sudo apt update --fix-missing</span></span>
<span class="line"><span>$ sudo apt install -f</span></span>
<span class="line"><span>$ sudo dpkg --configure -a</span></span>
<span class="line"><span>$ sudo apt upgrade</span></span>
<span class="line"><span>$ sudo apt dist-upgrade</span></span></code></pre></div><p>最后，使用命令重启系统：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo reboot</span></span></code></pre></div><p>你现在可以像往常一样登录到你的 Ubuntu 系统。</p><p>我做完这些步骤后，我 Ubuntu 18.04 测试系统中的所有数据都还在，一切都之前的一样。此方法可能不适用于所有人。但是，这个小小的技巧对我有用，并且比重装节省了一些时间。如果你了解其他更好的方法，请在评论区告诉我。我也会在本指南中添加它们。</p><p>这是这些了。希望这篇文章有用。</p><p>还有更多好东西。敬请关注！</p><p>干杯!</p><hr>`,10)),u("p",null,[t[6]||(t[6]=n("via: ")),a(s,{href:"https://www.ostechnix.com/how-to-fix-broken-ubuntu-os-without-reinstalling-it/"},{default:p(()=>t[5]||(t[5]=[n("https://www.ostechnix.com/how-to-fix-broken-ubuntu-os-without-reinstalling-it/")])),_:1})]),u("p",null,[t[11]||(t[11]=n("作者：")),a(s,{href:"https://www.ostechnix.com/author/sk/"},{default:p(()=>t[7]||(t[7]=[n("SK")])),_:1}),t[12]||(t[12]=n(" 选题：")),a(s,{href:"https://github.com/lujun9972"},{default:p(()=>t[8]||(t[8]=[n("lujun9972")])),_:1}),t[13]||(t[13]=n(" 译者：")),a(s,{href:"https://github.com/geekpi"},{default:p(()=>t[9]||(t[9]=[n("geekpi")])),_:1}),t[14]||(t[14]=n(" 校对：")),a(s,{href:"https://github.com/wxy"},{default:p(()=>t[10]||(t[10]=[n("wxy")])),_:1})]),u("p",null,[t[17]||(t[17]=n("本文由 ")),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>t[15]||(t[15]=[n("LCTT")])),_:1}),t[18]||(t[18]=n(" 原创编译，")),a(s,{href:"https://linux.cn/"},{default:p(()=>t[16]||(t[16]=[n("Linux中国")])),_:1}),t[19]||(t[19]=n(" 荣誉推出"))])])}const C=i(d,[["render",b]]);export{h as __pageData,C as default};
